python3 -c "
import serial, time
s = serial.Serial('/dev/ttyUSB0', 115200, timeout=1)
time.sleep(0.5)
end = time.time() + 15
while time.time() < end:
    if s.in_waiting:
        for line in s.read_all().decode(errors='replace').splitlines():
            if line.strip(): print(line)
s.close()
"
